css:
/* Blockworks. Original voxel ledges and four golem sprite sheets are embedded for a single-file import. */
:root {
  --blockworks-openai: url("data:image/webp;base64,");
  --blockworks-claude: url("data:image/webp;base64,");
  --blockworks-gemini: url("data:image/webp;base64,");
  --blockworks-opencode: url("data:image/webp;base64,");
}
:root.dark { --blockworks-terrain: url("data:image/webp;base64,"); --blockworks-ground: #171f27; }
:root:not(.dark) { --blockworks-terrain: url("data:image/webp;base64,"); --blockworks-ground: #e0ebd3; }

[data-workspace-area="conversation"]:not([data-side-chat-pane] *) {
  position: relative;
  isolation: isolate;
  container-type: size;
  background: var(--blockworks-terrain) center bottom / max(100%, 480px) clamp(36px, 16cqh, 76px) no-repeat var(--blockworks-ground) !important;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *):has(.messages-timeline-scroll [data-timeline-row-kind]) {
  background-image: linear-gradient(to bottom, transparent, var(--blockworks-ground)), var(--blockworks-terrain) !important;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *):has(.messages-timeline-scroll [data-timeline-row-kind])::before,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *):has(.messages-timeline-scroll [data-timeline-row-kind])::after,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *):has(.messages-timeline-scroll [data-timeline-row-kind]) > [data-assistant-citation-viewport]::before,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *):has(.messages-timeline-scroll [data-timeline-row-kind]) > [data-assistant-citation-viewport]::after {
  filter: opacity(.26);
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport] { position: relative; }
[data-chat-composer-main-surface],
[data-user-message-bubble] { border-radius: 5px !important; }
[data-chat-composer-main-surface] {
  background-color: var(--composer, var(--card)) !important;
  box-shadow: inset 0 1px 0 #fff2, 0 3px 0 #0004;
}
[data-chat-composer-main-surface] :is([data-chat-composer-compact-send], button[type="submit"]) {
  border-radius: 4px;
}
[data-chat-composer-main-surface] :is([data-chat-composer-compact-send], button[type="submit"]):not(:disabled) {
  background: var(--accent);
  color: var(--accent-ink, var(--accent-foreground));
  box-shadow: inset 0 1px 0 #fff3, inset 0 -2px 0 #0003;
}

[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::before,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::after,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::before,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::after {
  position: absolute;
  left: 0;
  top: 0;
  z-index: -1;
  pointer-events: none;
  width: var(--blockworks-size);
  height: var(--blockworks-size);
  image-rendering: pixelated;
  background: var(--blockworks-sprite, var(--blockworks-openai)) no-repeat 0 0 / 400% 100%;
  transform: translate(var(--blockworks-from), var(--blockworks-height));
  animation: t3-blockworks-walk var(--blockworks-pace, 8s) steps(24, end) infinite,
             t3-blockworks-feet 0.8s steps(4, end) infinite;
  animation-play-state: var(--theme-motion-state, running);
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::before {
  content: "";
  --blockworks-size: clamp(34px, 10cqw, 62px);
  --blockworks-from: max(12px, calc(24cqw - var(--blockworks-size) / 2));
  --blockworks-to: calc(54cqw - var(--blockworks-size) / 2);
  --blockworks-height: calc(100cqh - var(--blockworks-size) - clamp(5px, 2.5cqh, 13px));
  animation-delay: -1s, 0s;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::after,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::before,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::after {
  --blockworks-size: clamp(25px, 7.5cqw, 44px);
  opacity: .94;
  --blockworks-from: max(4px, calc(var(--blockworks-left) * 1cqw - var(--blockworks-size) / 2));
  --blockworks-to: min(calc(100cqw - var(--blockworks-size) - 4px), calc(var(--blockworks-right) * 1cqw - var(--blockworks-size) / 2));
  --blockworks-height: calc(100cqh - var(--blockworks-size) - var(--blockworks-ridge));
  animation-delay: var(--blockworks-phase), -.2s;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::after {
  --blockworks-left: 9; --blockworks-right: 30; --blockworks-ridge: clamp(16px, 5cqh, 31px);
  --blockworks-pace: 5.6s; --blockworks-phase: -.8s;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::before {
  --blockworks-left: 71; --blockworks-right: 94; --blockworks-ridge: clamp(14px, 4.5cqh, 29px);
  --blockworks-pace: 6.4s; --blockworks-phase: -2.3s;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::after {
  --blockworks-left: 56; --blockworks-right: 68; --blockworks-ridge: clamp(9px, 4cqh, 20px);
  --blockworks-pace: 8.6s; --blockworks-phase: -3.5s;
}
